// Inter (OFL-1.1), subset to Basic Latin + Latin-1 Supplement + Latin
// Extended-A/B + General Punctuation + the full Currency Symbols block
// (U+20A0-20CF, which includes U+20B5 Ghana Cedi Sign), instanced from the
// upstream variable font (google/fonts, ofl/inter) at wght 400/700, opsz 14,
// then subsetted with fontTools. Embedded into invoice PDFs (see
// invoice-pdf.ts) because jsPDF's built-in "helvetica" font only supports
// WinAnsiEncoding, a single-byte charset with no Ghana Cedi Sign glyph — a
// codepoint outside that charset gets silently truncated to its low byte
// (0x20B5 & 0xFF = 0xB5), which WinAnsi/Latin-1 decodes as µ (MICRO SIGN),
// not an error. Regenerating: instantiate the variable TTF at the desired
// weight with fontTools.varLib.instancer, then
// `fonttools subset in.ttf --unicodes="U+0020-007E,U+00A0-024F,U+2000-206F,U+20A0-20CF" --output-file=out.ttf --layout-features="*" --glyph-names --symbol-cmap --legacy-cmap --notdef-glyph --notdef-outline --recommended-glyphs --name-IDs="*" --name-legacy --name-languages="*"`,
// then base64-encode the result.
export const INTER_REGULAR_TTF_BASE64 =
  "";
